import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin, uniqueName } from './helpers';

test.describe(`sales rep: add a new contact with their info (name, email, phone, company)`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a rep adds a contact, every team member sees it in the contact list within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);

    // Put both reps in the same shared workspace before either touches data.
    await inviteAndJoin(pageA, pageB);

    const name = uniqueName('contact');
    await pageA.getByTestId('field-name').fill(name);
    await pageA.getByTestId('field-email').fill(`${name}@example.com`);
    await pageA.getByTestId('field-phone').fill('555-0101');
    await pageA.getByTestId('field-company').fill('Acme Co');
    await pageA.getByTestId('action-add_contact').click();

    await expect(pageB.getByTestId(/^item-contact-/).filter({ hasText: name })).toBeVisible({
      timeout: 5_000,
    });

    await ctxA.close();
    await ctxB.close();
  });
});
